export const NARRATION_SENTENCES: NarrationSentence[] = [
  { scene: 1, part: 1, start: 0.109, end: 6.136, text: "In the summer of 2022, Saudi Arabia showed the world a city that looked like science fiction." },
  { scene: 1, part: 1, start: 6.136, end: 15.183, text: "Two walls of mirrored glass, five hundred metres tall, running one hundred and seventy kilometres across the desert." },
  { scene: 1, part: 1, start: 15.183, end: 16.261, text: "Nine million residents." },
  { scene: 1, part: 1, start: 16.261, end: 17.46, text: "No cars." },
  { scene: 1, part: 1, start: 17.46, end: 18.521, text: "No streets." },
  { scene: 1, part: 1, start: 18.521, end: 19.681, text: "It was called The Line." },
  { scene: 2, part: 1, start: 19.681, end: 27.068, text: "Less than two years later, reports said only about two point four kilometres of it was expected to be finished by 2030." },
  { scene: 2, part: 1, start: 27.068, end: 31.338, text: "So what happened to the city that promised to change how humans live?" },
  { scene: 3, part: 1, start: 31.338, end: 35.286, text: "To understand The Line, you have to start with oil." },
  { scene: 3, part: 1, start: 35.286, end: 39.599, text: "For decades, oil has paid for almost everything in Saudi Arabia." },
  { scene: 3, part: 1, start: 39.599, end: 43.085, text: "But oil is finite, and its future is uncertain." },
  { scene: 3, part: 1, start: 43.085, end: 50.304, text: "In April 2016, the kingdom's young deputy crown prince, Mohammed bin Salman, said so on national television." },
  { scene: 3, part: 1, start: 50.304, end: 53.901, text: "Launching a plan called Vision 2030, he declared:" },
  { scene: 3, part: 1, start: 53.901, end: 57.631, text: "\"We have developed a case of oil addiction in Saudi Arabia.\"" },
  { scene: 3, part: 1, start: 57.631, end: 60.543, text: "Vision 2030 was meant to be the cure." },
  { scene: 3, part: 1, start: 60.543, end: 66.926, text: "Tourism, technology, entertainment and industry would carry the economy when oil no longer could." },
  { scene: 4, part: 1, start: 66.926, end: 74.11, text: "In October 2017, at an investment conference in Riyadh, the crown prince unveiled the plan's boldest symbol." },
  { scene: 4, part: 1, start: 74.11, end: 84.028, text: "NEOM: a new region of more than twenty-six thousand square kilometres in the far northwest of the kingdom, where the Red Sea meets the mountains near Jordan and Egypt." },
  { scene: 4, part: 1, start: 84.028, end: 87.631, text: "The headline figure was five hundred billion dollars." },
  { scene: 4, part: 1, start: 87.631, end: 94.228, text: "NEOM was meant to contain several projects: an industrial port, a mountain resort, luxury islands." },
  { scene: 4, part: 1, start: 94.228, end: 96.966, text: "But one idea quickly became its face." },
  { scene: 4, part: 1, start: 96.966, end: 103.678, text: "In January 2021, the crown prince announced a city for a million people, built in a single line." },
  { scene: 4, part: 1, start: 103.678, end: 104.865, text: "Zero cars." },
  { scene: 4, part: 1, start: 104.865, end: 106.025, text: "Zero streets." },
  { scene: 4, part: 1, start: 106.025, end: 107.808, text: "Zero carbon emissions." },
  { scene: 5, part: 1, start: 107.808, end: 112.37, text: "Eighteen months later, the designs arrived, and the ambition had grown." },
  { scene: 5, part: 1, start: 112.37, end: 120.323, text: "The Line would now be two parallel structures, each five hundred metres tall, taller than all but about a dozen buildings on Earth." },
  { scene: 5, part: 1, start: 120.323, end: 127.246, text: "They would face each other across a gap of just two hundred metres, and stretch for the full one hundred and seventy kilometres." },
  { scene: 5, part: 1, start: 127.246, end: 132.973, text: "Their outer walls would be mirrors, reflecting the desert so the city might almost vanish into it." },
  { scene: 6, part: 1, start: 132.973, end: 135.792, text: "Inside, the city would be stacked vertically." },
  { scene: 6, part: 1, start: 135.792, end: 143.786, text: "Homes, schools, offices and parks layered on top of one another, so that everything a resident needed would be within a five-minute walk." },
  { scene: 6, part: 1, start: 143.786, end: 149.162, text: "Beneath it all, a high-speed railway would run from one end to the other in about twenty minutes." },
  { scene: 6, part: 1, start: 149.162, end: 153.944, text: "The long-term ambition was nine million residents, roughly the size of London." },
  { scene: 6, part: 1, start: 153.944, end: 158.799, text: "NEOM said the design would leave ninety-five percent of NEOM's land untouched." },
  { scene: 6, part: 1, start: 158.799, end: 161.424, text: "It was a genuinely radical idea." },
  { scene: 6, part: 1, start: 161.424, end: 167.103, text: "Instead of sprawling outward, a city would rise upward, and nature would surround it." },
  { scene: 6, part: 1, start: 167.103, end: 172.452, text: "But radical ideas still have to survive contact with physics, money and people." },
  { scene: 7, part: 1, start: 172.452, end: 174.054, text: "Start with the walls." },
  { scene: 7, part: 1, start: 174.054, end: 179.125, text: "Half a kilometre of glass facing open desert means relentless sun and wind." },
  { scene: 7, part: 1, start: 179.125, end: 191.909, text: "Architects and engineers questioned how the structure would resist wind along its full length, how much heat its mirrored surfaces would trap, and how much carbon would be released simply producing the steel, concrete and glass." },
  { scene: 7, part: 1, start: 191.909, end: 193.884, text: "Then there were the birds." },
  { scene: 7, part: 1, start: 193.884, end: 204.565, text: "The region lies on a major migration route, and in 2024 conservation scientists warned that The Line was likely to pose a substantial risk to migratory species." },
  { scene: 7, part: 1, start: 204.565, end: 210.772, text: "NEOM said the facades would be treated to reduce collisions, with nature corridors along migration paths." },
  { scene: 8, part: 2, start: 0.11, end: 1.939, text: "And the land was not empty." },
  { scene: 8, part: 2, start: 1.939, end: 4.449, text: "Members of the Huwaitat tribe lived there." },
  { scene: 8, part: 2, start: 4.449, end: 11.557, text: "In April 2020, one of them, Abdul Rahim al-Huwaiti, posted videos refusing to leave his home." },
  { scene: 8, part: 2, start: 11.557, end: 15.918, text: "Shortly afterwards, he was shot dead by Saudi security forces." },
  { scene: 8, part: 2, start: 15.918, end: 20.607, text: "Saudi authorities said he had barricaded himself inside and opened fire." },
  { scene: 8, part: 2, start: 20.607, end: 27.9, text: "Human rights groups dispute that account, and United Nations experts wrote to the Saudi government raising concerns about his death." },
  { scene: 8, part: 2, start: 27.9, end: 38.934, text: "In 2024, a former Saudi intelligence officer told the BBC that lethal force had been authorised to clear the area, a claim the BBC could not independently verify." },
  { scene: 8, part: 2, start: 38.934, end: 42.474, text: "Saudi authorities say residents were offered compensation." },
  { scene: 8, part: 2, start: 42.474, end: 46.309, text: "But in the end, the problem that mattered most was money." },
  { scene: 9, part: 2, start: 46.309, end: 52.518, text: "In April 2024, Bloomberg reported that Saudi officials had sharply cut their expectations." },
  { scene: 9, part: 2, start: 52.518, end: 65.864, text: "By 2030, according to a person familiar with the plans, they expected about two point four kilometres of The Line to be completed, and fewer than three hundred thousand residents, down from a hoped-for one point five million." },
  { scene: 9, part: 2, start: 65.864, end: 70.813, text: "The sovereign wealth fund paying for most of NEOM had not yet approved that year's budget." },
  { scene: 9, part: 2, start: 70.813, end: 74.13, text: "That is where the two point four kilometre figure comes from." },
  { scene: 9, part: 2, start: 74.13, end: 81.705, text: "It was a reported target for what would be finished by 2030, never officially announced, and never the size of the whole project." },
  { scene: 9, part: 2, start: 81.705, end: 86.188, text: "But over the next two years, the direction of travel only became clearer." },
  { scene: 10, part: 2, start: 86.188, end: 92.47, text: "In November 2024, NEOM's long-serving chief executive left without a public explanation." },
  { scene: 10, part: 2, start: 92.47, end: 99.943, text: "His replacement, Aiman al-Mudaifer, came from the sovereign wealth fund, and began a strategic review." },
  { scene: 10, part: 2, start: 99.943, end: 101.119, text: "A new leader." },
  { scene: 10, part: 2, start: 101.119, end: 102.047, text: "A new review." },
  { scene: 10, part: 2, start: 102.047, end: 103.43, text: "And soon, new priorities." },
  { scene: 11, part: 2, start: 103.43, end: 106.126, text: "Yet on the ground, the work was real." },
  { scene: 11, part: 2, start: 106.126, end: 109.787, text: "Excavators had been cutting into the desert since 2022." },
  { scene: 11, part: 2, start: 109.787, end: 115.196, text: "NEOM's own updates showed thousands of foundation piles being driven deep into the ground." },
  { scene: 11, part: 2, start: 115.196, end: 118.657, text: "Whatever happens next, part of The Line exists." },
  { scene: 11, part: 2, start: 118.657, end: 120.879, text: "It just lies beneath the sand." },
  { scene: 12, part: 2, start: 120.879, end: 129.322, text: "Then, in April 2026, the head of Saudi Arabia's Public Investment Fund, Yasir Al-Rumayyan, said something remarkable." },
  { scene: 12, part: 2, start: 129.322, end: 133.375, text: "Asked whether The Line needed to exist by 2030, he said:" },
  { scene: 12, part: 2, start: 133.375, end: 136.47, text: "\"It would be good to have, but it's not a must.\"" },
  { scene: 12, part: 2, start: 136.47, end: 141.618, text: "What the kingdom must have, he said, was Oxagon, NEOM's industrial port." },
  { scene: 12, part: 2, start: 141.618, end: 145.288, text: "He also insisted that no NEOM projects had been cancelled." },
  { scene: 12, part: 2, start: 145.288, end: 154.739, text: "A month later, Semafor reported that work on The Line had been halted until at least after 2030, with money redirected towards ports and data centres." },
  { scene: 12, part: 2, start: 154.739, end: 161.425, text: "By the summer, NEOM's website no longer led with nine million residents or a city without cars." },
  { scene: 12, part: 2, start: 161.425, end: 169.225, text: "The Line was now \"a core component\" of NEOM's long-term vision, advancing through a \"phased, demand-led approach.\"" },
  { scene: 13, part: 2, start: 169.225, end: 173.95, text: "So did the hundred-and-seventy-kilometre city really shrink to two point four?" },
  { scene: 13, part: 2, start: 173.95, end: 177.265, text: "The honest answer is more interesting than yes or no." },
  { scene: 13, part: 2, start: 177.265, end: 180.167, text: "Officially, The Line has not been cancelled." },
  { scene: 13, part: 2, start: 180.167, end: 185.62, text: "The two point four kilometre figure was a reported target for 2030, not an official one." },
  { scene: 13, part: 2, start: 185.62, end: 190.332, text: "It was never a cut to the whole plan, and it is not a measure of what has been built." },
  { scene: 13, part: 2, start: 190.332, end: 191.719, text: "But look at the pattern." },
  { scene: 13, part: 2, start: 191.719, end: 198.296, text: "The reported population goal for 2030 fell from one and a half million to fewer than three hundred thousand." },
  { scene: 13, part: 2, start: 198.296, end: 201.501, text: "Work was reportedly pushed beyond 2030." },
  { scene: 13, part: 2, start: 201.501, end: 206.193, text: "The long-term promise of nine million residents vanished from the official description." },
  { scene: 13, part: 2, start: 206.193, end: 210.62, text: "And the people funding it said, in public, that it was no longer essential." },
  { scene: 13, part: 2, start: 210.62, end: 213.799, text: "The Line didn't collapse in a single dramatic moment." },
  { scene: 13, part: 2, start: 213.799, end: 219.226, text: "It shrank step by step, through budgets, reviews and rewritten web pages." },
  { scene: 14, part: 2, start: 219.226, end: 221.258, text: "And the new phrase explains why." },
  { scene: 14, part: 2, start: 221.258, end: 226.04, text: "\"Demand-led\" means building when people and businesses actually want to come." },
  { scene: 14, part: 2, start: 226.04, end: 228.383, text: "The original Line worked the other way round." },
  { scene: 14, part: 2, start: 228.383, end: 232.632, text: "Build the future first, and trust that nine million people would follow." },
  { scene: 14, part: 2, start: 232.632, end: 235.132, text: "History is full of planned cities." },
  { scene: 14, part: 2, start: 235.132, end: 238.276, text: "Some, like Brasília, became living capitals." },
  { scene: 14, part: 2, start: 238.276, end: 241.811, text: "Many others grew far more slowly than their plans promised." },
  { scene: 14, part: 2, start: 241.811, end: 243.825, text: "Cities are not simply built." },
  { scene: 14, part: 2, start: 243.825, end: 247.692, text: "They grow, from jobs, families and reasons to stay." },
  { scene: 14, part: 2, start: 247.692, end: 255.353, text: "The Line asked an important question: could we live more densely, with less sprawl, less driving and more space for nature?" },
  { scene: 14, part: 2, start: 255.353, end: 261.591, text: "That question doesn't disappear just because the answer, at one hundred and seventy kilometres, proved too expensive." },
  { scene: 15, part: 2, start: 261.591, end: 265.947, text: "Somewhere in northwest Saudi Arabia, foundations are waiting in the sand." },
  { scene: 15, part: 2, start: 265.947, end: 273.924, text: "Whether they become the first piece of a new kind of city, or a monument to the limits of ambition, may not be decided until the 2030s." },
  { scene: 15, part: 2, start: 273.924, end: 279.434, text: "Was The Line a vision ahead of its time, or a warning about building the future from the top down?" },
  { scene: 15, part: 2, start: 279.434, end: 281.413, text: "Tell us what you think in the comments." },
  { scene: 15, part: 2, start: 281.413, end: 288.614, text: "And if you want more stories about the world's boldest megaprojects, and what really happened to them, subscribe to EmpireAtlas." },
];
